"""The book's syntax explanations at the exact point where a beginner needs them."""
FRAMES = {
'c':'''#include <stdio.h> предоставляет объявления стандартного ввода и вывода. int main(void) — начало выполняемой программы: main является специальным именем входа, void здесь означает отсутствие параметров. Открывающая фигурная скобка начинает тело, закрывающая завершает. Точка с запятой заканчивает обычную команду. return 0 завершает main с кодом успешного окончания; этот ноль не печатается как ответ задачи. В printf("%s\\n", "Hello") часть %s обозначает место текста, Hello — передаваемый текст, а \\n задаёт перевод строки. Для вывода целого числа используется подходящий спецификатор %d. Формат и тип значения должны соответствовать.''',
'cpp':'''#include <iostream> предоставляет объявления консольных потоков. int main() — точка начала программы. Фигурные скобки ограничивают её тело, точка с запятой заканчивает обычную команду. std:: указывает стандартное пространство имён. std::cout — поток вывода; << в этой записи передаёт в него значение справа. Текст в кавычках показывается без самих кавычек. "\\n" задаёт перевод строки, а не печатает буквы n. return 0 сообщает об успешном завершении main и не является печатью нуля. Средство чтения std::cin использует другое направление >>.''',
'csharp':'''using System позволяет использовать короткие имена средств пространства System. class Program объединяет части нашего учебного приложения. static void Main() — его точка входа: static позволяет запуск без предварительно созданного экземпляра Program, void означает отсутствие возвращаемого значения. Скобки после имени относятся к параметрам или аргументам, фигурные скобки ограничивают тело. Console.WriteLine получает значение в круглых скобках и показывает его с переводом строки. Точка отделяет имя действия от объекта или типа, к которому обращаемся. Точка с запятой завершает обычную команду.''',
'python':'''Файл Python выполняется обычными командами сверху вниз. print — имя стандартной функции вывода. Круглые скобки задают её вызов, внутри находятся передаваемые значения. Кавычки ограничивают текст; сами они обычно не выводятся. print по умолчанию добавляет перевод строки. Отступы задают принадлежность команд к функции, условию или циклу. Поэтому одинаковая на вид перестановка пробелов способна изменить программу или вызвать ошибку. После заголовка такого блока стоит двоеточие. Комментарий после # объясняет запись человеку и не выполняется как команда.''',
'java':'''public class Main объявляет доступный класс Main; для этого public-класса файл называется Main.java. Внутри находится public static void main(String[] args) — вход приложения. static означает вызов без создания Main, void — отсутствие возвращаемого значения. args содержит аргументы запуска; ввод из поля программы читается другим средством, а не из этого массива автоматически. System.out — стандартный поток вывода, println — его действие печати с переводом строки. Фигурные скобки ограничивают тела класса и метода, а точка с запятой завершает обычную команду.''',
'javascript':'''В Node.js обычные команды main.js выполняются в порядке запуска файла. console — предоставленное средой средство работы с консолью, log — действие вывода. Скобки после log передают аргументы, а кавычки ограничивают текст. const создаёт имя, которому нельзя присвоить другое значение; let допускает последующее присваивание. Эти правила не означают автоматическую неизменяемость вложенного объекта. Фигурные скобки используются для блоков и объектов по контексту. Чтение ввода в Node выполняется через стандартные средства среды, а не через браузерное окно prompt.''',
'go':'''package main обозначает пакет исполняемого приложения. import "fmt" подключает пакет форматирования и консольных операций. func main() — точка входа; её команды находятся в фигурных скобках. fmt.Println обращается к действию Println пакета fmt и показывает переданные значения с переводом строки. Заглавная первая буква связана с доступностью имени из другого пакета. Запись := создаёт локальное имя с выведенным типом, = меняет уже существующее. Подключённый, но неиспользуемый пакет мешает сборке, поэтому лишние импорты нужно удалять, а не игнорировать предупреждение.''',
}
DETAILS = {
('c','records'):'''struct Product объявляет форму записи. Внутри перечислены имена и типы её полей. const char *title в этом опыте обращается к неизменяемому тексту названия; строковый литерал не нужно освобождать вручную. При создании {1, "Cat", 3} значения соответствуют полям в порядке объявления. Точка product.stock обращается к одному полю конкретной записи. Это отличается от выбора элемента массива по номеру.''',
('cpp','records'):'''Объявление struct Product задаёт поля каждой записи. std::string хранит название как стандартный строковый объект. Product product{1, "Cat", 3} создаёт запись с тремя значениями в соответствующем порядке. Запись product.title обращается к полю названия. Создание второй product-подобной записи с другими значениями не должно менять первую автоматически. Владение и копирование сложных вложенных данных разберём отдельными опытами.''',
('csharp','records'):'''record Product(int Id, string Title, int Stock) кратко объявляет запись с именованными компонентами. new Product(1, "Cat", 3) создаёт отдельное значение по этому объявлению; такой вызов создания называют конструктором. Через product.Title и product.Stock читаются соответствующие свойства. Регистр букв важен: Title и title являются разными написаниями. На этой ступени читаем поля; детали равенства и изменения записей разберём позднее.''',
('java','records'):'''record Product объявляет компактную запись с компонентами id, title и stock. new Product(1, "Cat", 3) создаёт экземпляр, передавая значения в соответствующем порядке. Для чтения компонентов Java-record предоставляет методы title() и stock(), поэтому круглые скобки в этих обращениях обязательны. Это не те же правила, что у свойства C#. Имена и их регистр сравнивай именно с объявлением своего языка.''',
('python','records'):'''В начальном опыте связанная запись представлена уже знакомым словарём. Ключи "id", "title" и "stock" называют свойства одного товара. product["title"] получает значение по ключу, а не по числовой позиции. Кавычки нужны, потому что имя ключа является текстом. Классы и dataclass позволяют позже описать такую модель другим способом; для понимания первого опыта они пока не требуются.''',
('javascript','records'):'''Фигурные скобки после присваивания создают объект с именованными свойствами id, title и stock. product.title читает свойство конкретного объекта. const запрещает присвоить имени product другой объект, но не делает поля неизменяемыми. Для изменения остатка можно присвоить новое product.stock после проверки условий. Не путай фигурные скобки объекта со скобками тела функции: их роль определяется местом записи.''',
('go','records'):'''type Product struct объявляет собственный тип записи. Product{ID: 1, Title: "Cat", Stock: 3} создаёт значение с явно подписанными полями. Через product.Title читается название. Заглавные имена полей позволяют доступ из других пакетов и пригодятся стандартным средствам обмена данными. В текущем опыте всё находится в package main. Указательный метод для изменения остатка будет отдельным следующим шагом.''',
('c','input'):'''scanf("%d", &count) пытается прочитать целое и записать его в count. %d задаёт формат, &count передаёт адрес места для результата. На этой ступени достаточно понимать назначение адреса; подробную модель указателей изучим отдельно. Возвращаемое число показывает, сколько нужных значений прочитано. Проверка != 1 обнаруживает отказ прочитать одно число. fgets для имени получает буфер и его размер; strcspn в полном примере находит границу перевода строки, чтобы имя не печаталось вместе с ним.''',
('cpp','input'):'''std::cin >> count читает число из входного потока. В условии !(std::cin >> count) отрицание ! проверяет неудачу операции. Для целой строки применяется std::getline: оно не обрывает имя на первом пробеле. В полном опыте сначала читается строка имени, затем возраст. Круглые скобки группируют отдельное действие чтения; return 1 заканчивает программу при неподходящем входе. Поэтому дальнейшая печать не использует число, которого не удалось получить.''',
('csharp','input'):'''Console.ReadLine получает строку или отсутствие строки. ?? "" выбирает пустой текст при отсутствии, но не превращает его автоматически в допустимое число. int.Parse выполняет числовое преобразование и может сообщить об ошибке. В полном образце предполагается корректный возраст. Сочетание $"{name} {age}" подставляет значения имён в текст; фигурные скобки внутри такой строки отличаются от скобок тела метода.''',
('java','input'):'''new Scanner(System.in) создаёт средство чтения стандартного входа. nextLine получает очередную строку, а nextInt пытается прочитать целое по правилам Scanner. В полном опыте чтение двух строк отдельно делает границу имени и возраста явной. Integer.parseInt преобразует текст возраста в int. Неподходящий текст может привести к NumberFormatException; обработка этого отказа разбирается в теме ошибок. import предоставляет имя Scanner, а не читает данные сам.''',
('javascript','input'):'''require("node:fs") получает стандартный модуль файловых операций Node. readFileSync(0, "utf8") читает стандартный вход как текст в UTF-8; число 0 здесь обозначает вход, а не данные задачи. split делит текст по границам строк, а Number пытается получить числовое значение. Пустой текст и неправильный текст требуют отдельной проверки, когда запрещены условием. В начальном опыте ввод корректен; дальше мы явно проверяем допустимость преобразования.''',
('go','input'):'''fmt.Scan(&count) получает адрес переменной для записи прочитанного числа. В более подробном опыте bufio.Scanner читает строки: Scan продвигается к следующей, Text получает её содержание. strconv.Atoi преобразует строку в int и возвращает два результата: число и возможную ошибку. Проверка err != nil отделяет отказ от успеха. return без значения завершает нашу main. Не путай возвращённую ошибку с корректным числом ноль.''',
('python','input'):'''input() возвращает текст без завершающего перевода строки. Даже если введено 20, результат чтения сам по себе является строкой. int(...) преобразует подходящую запись целого числа. Для имени такое преобразование не нужно. print(name, age) передаёт два отдельных аргумента и по умолчанию разделяет их пробелом. Сначала прочитай первую строку целиком, затем вторую, не заменяя имя числовым чтением.''',
('c','collections'):'''В этой программе возможные ключи заранее известны: цифры 0…9. Поэтому counts содержит десять целых счётчиков. {0} задаёт нулевое начало для всего массива. counts[digits[i]] сначала получает очередную цифру, затем использует её как номер нужного счётчика. Увеличение ++ меняет только выбранную ячейку. Для произвольных слов такой прямой номер уже не получается: понадобится другая структура, которую нельзя считать встроенным словарём C.''',
('cpp','collections'):'''В std::map<int, int> первый int задаёт тип ключа, второй — тип счётчика. Угловые скобки здесь описывают параметры типа, а не сравнение чисел. counts[digit] обращается к значению ключа; для отсутствующего ключа в этом примере создаётся нулевой счётчик, после чего ++ увеличивает его. Цикл for по списку значений берёт одну цифру на каждом шаге. Эта конкретная map имеет упорядоченные ключи, но это не общее обещание для любой коллекции.''',
('csharp','collections'):'''Dictionary<int, int> связывает целочисленный ключ со счётчиком. var выводит тип из правой части, а не отменяет наличие типа. GetValueOrDefault получает сохранённый счётчик либо начальный ноль. После прибавления результат записывается через counts[digit]. foreach выбирает очередную цифру, не её индекс. Важно сохранить изменённый счётчик в словарь: одно вычисление старого значения плюс один само по себе не меняет хранилище.''',
('java','collections'):'''HashMap<Integer, Integer> хранит объектные обёртки целых ключей и значений. getOrDefault получает число для ключа или заданный ноль. put сохраняет новый результат под тем же ключом. var позволяет компилятору вывести конкретный тип переменной из создания объекта. Обход for берёт сами цифры. Вызов get(3) получает счётчик ключа 3, а не четвёртую позицию списка: у Map другая модель доступа.''',
('python','collections'):'''Пустые фигурные скобки {} здесь создают словарь. get(digit, 0) возвращает текущий счётчик или ноль для отсутствующего ключа. После сложения присваивание counts[digit] = ... сохраняет новый счётчик. Квадратные скобки обращаются к значению ключа, а не обязательно к номеру позиции: смысл зависит от коллекции. Входной список цифр обходится слева направо, но результат задачи — один счётчик, а не печать всего словаря.''',
('javascript','collections'):'''new Map() создаёт хранилище пар. get(digit) получает значение ключа; при отсутствии получается undefined. ?? 0 выбирает начальный ноль только при соответствующем отсутствии, после чего set сохраняет увеличенное значение. Это отличается от доступа к обычному объекту через квадратные скобки. for...of выдаёт сами значения списка. Для результата выводится get(3), а не объект Map целиком.''',
('go','collections'):'''make(map[int]int) создаёт map с ключами и значениями int. Чтение отсутствующего ключа даёт нулевое значение int, поэтому увеличение counts[digit]++ начинает новый счётчик с единицы. range по slice выдаёт индекс и значение. Подчёркивание _ отбрасывает неиспользуемый индекс, оставляя digit. Для проверки отсутствия, отличного от сохранённого нуля, применяется отдельная форма с дополнительным ok.''',
}


def notes(lang, lesson_id):
    parts=lesson_id.split('.')
    topic=parts[-1]
    if '.zero.' in lesson_id and topic=='input':
        return {
          'c':'int count создаёт место для целого числа. В scanf("%d", &count) формат %d требует целое, а &count передаёт адрес места для его записи. Результат scanf показывает число прочитанных значений; проверка != 1 обнаруживает отказ. При отказе return 1 заканчивает программу. При успехе printf показывает count + 1. Подробную работу адресов будем изучать отдельно, но назначение & в этом опыте уже известно.',
          'cpp':'std::cin >> count пытается прочитать число в count. В записи if (!(std::cin >> count)) знак ! означает отрицание успешного чтения: при неудаче выполняется return 1. При успехе программа доходит до std::cout и показывает count + 1. Чтение >> и вывод << направлены по-разному; они не являются текстом, который надо вводить в поле данных.',
          'csharp':'Console.ReadLine получает строку. ?? "" выбирает пустой текст, если строки нет; допустимым числом пустой текст от этого не становится. int.Parse(text) преобразует подходящую запись целого в число count. Console.WriteLine(count + 1) сначала считает прибавление, затем показывает результат. Для этого опыта передаём корректное число; обработку неверного текста разберём отдельно.',
          'python':'input() читает текст одной строки без завершающего перевода. Переменная text хранит именно этот текст. int(text) получает число count из подходящей записи. print(count + 1) сначала вычисляет новое числовое значение, затем показывает его. Без преобразования попытка прибавить число к тексту имела бы другое, неподходящее поведение. Пока используем корректный числовой ввод.',
          'java':'java.util.Scanner — полное имя средства чтения. new создаёт его с источником System.in, то есть стандартным входом. input.nextInt() пытается получить очередное целое и сохранить в count. System.out.println показывает count + 1. Имя input относится к созданному объекту чтения, а не к полю интерфейса автоматически. В этом опыте передаём корректное число.',
          'javascript':'require("node:fs") получает стандартный модуль Node. readFileSync(0, "utf8") читает стандартный вход как текст: 0 обозначает источник, а не само число задачи. trim убирает внешние пробельные знаки. Number(text) пытается получить число count. console.log(count + 1) показывает результат арифметики. Проверка пустого и неправильного текста будет отдельным опытом.',
          'go':'var count int объявляет переменную целого типа. fmt.Scan(&count) передаёт адресу переменной прочитанное число. Знак & здесь нужен для записи результата в это место. fmt.Println(count + 1) сначала вычисляет прибавление, затем показывает число. На этом первом опыте ввод корректен; возвращаемые результаты Scan и проверку отказа рассмотрим в теме надёжного чтения.',
        }.get(lang,'')
    if topic=='input' and lang in FRAMES:
        return DETAILS[(lang,'input')]
    if len(parts)==2 and (lang,topic) in DETAILS:
        return DETAILS[(lang,topic)]
    if '.zero.' in lesson_id and topic=='start':
        return FRAMES.get(lang,'')
    return ''
